<?= $this->extend('layouts/customer') ?><?= $this->section('content') ?><h1 class="h2 mb-4">Gardening Packages</h1><div class="row g-4"><?php foreach($packages as $p): ?><div class="col-md-6 col-lg-4"><div class="card h-100 overflow-hidden"><?php if($p['main_image']): ?><img class="product-image w-100" src="<?= base_url($p['main_image']) ?>" alt="<?= esc($p['name']) ?>"><?php endif ?><div class="card-body"><h2 class="h5"><a class="text-dark text-decoration-none" href="<?= url_to('catalog.package',$p['slug']) ?>"><?= esc($p['name']) ?></a></h2><div><strong class="text-success">৳<?= number_format($p['package_price'],2) ?></strong> <del class="text-muted">৳<?= number_format($p['regular_total'],2) ?></del></div><div class="small text-success">Save ৳<?= number_format(max(0,$p['regular_total']-$p['package_price']),2) ?></div><div class="mt-2"><?= $p['available']>0?'Available':'Out of stock' ?></div></div></div></div><?php endforeach ?><?php if(!$packages): ?><p class="text-muted">No packages are available.</p><?php endif ?></div><div class="mt-4"><?= $pager->links() ?></div><?= $this->endSection() ?>
